/* Phrase candidates from bar-level energy and coarse timbre. All bounds are samples. */
(function(root){
function features(channels,start,end){let e=0,flux=0,zero=0,n=0;const step=Math.max(1,Math.floor((end-start)/4096));for(const ch of channels){for(let i=start+step;i<end;i+=step){const x=ch[i],prev=ch[i-step];e+=x*x;flux+=Math.max(0,Math.abs(x)-Math.abs(prev));zero+=(x>=0)!==(prev>=0)?1:0;n++}}return {energy:Math.sqrt(e/Math.max(1,n)),flux:flux/Math.max(1,n),zero:zero/Math.max(1,n)}}
function distance(a,b){return Math.abs(Math.log((a.energy+.001)/(b.energy+.001)))+Math.abs(a.zero-b.zero)*4+Math.abs(a.flux-b.flux)*2}
function find(channels,sr,bpm,beats,offset,bars,limit=8){const barSamples=sr*60/bpm*beats,first=Math.round(offset*sr),count=Math.floor((channels[0].length-first)/barSamples);if(count<bars)return [];const f=Array.from({length:count},(_,i)=>features(channels,first+Math.round(i*barSamples),first+Math.round((i+1)*barSamples)));const out=[];for(let i=0;i+bars<=count;i++){const start=first+Math.round(i*barSamples),end=first+Math.round((i+bars)*barSamples),begin=f[i],last=f[i+bars-1],next=f[i+bars],previous=f[i-1];const repeat=distance(begin,last),novelty=(previous?distance(previous,begin):0)+(next?distance(last,next):0),jump=Math.abs(channels[0][start]-channels[0][end-1]);const score=repeat+Math.min(1,jump)*.3-novelty*.12;out.push({start,end,bars,score,reason:repeat<.25?'similar opening and ending texture':novelty>.35?'change near a phrase boundary':'bar-aligned phrase; listen to confirm'});}return out.sort((a,b)=>a.score-b.score).slice(0,limit)}
const api={find,features};if(typeof module!=='undefined')module.exports=api;else root.PulsePhrase=api;
})(globalThis);
